"use server";

import { prisma } from "@/lib/db";
import { getSession } from "@/lib/server/session";
import { clinicDateKey, startOfClinicDay } from "@/lib/clinic-time";
import { coursePurchasesBetween } from "@/lib/server/course-revenue";
import { stalledFallbackDays } from "@/lib/server/stalled-threshold";

/**
 * Курсы пациентов для экранов.
 *
 * Раздел «Курсы», плитка в аналитике пациентов и строка «выпали из курса» на
 * «Сегодня» читали курсы из стора, а в стор они не попадали никогда: при
 * загрузке пациенту проставлялся пустой список. Экраны были живыми, данных за
 * ними не было — пустота выглядела как «не доехало».
 *
 * Теперь курс собирается из записей YCLIENTS (см. lib/courses/link.ts), и
 * читать его можно по-настоящему.
 */
/**
 * Курсы, проданные в этот день.
 *
 * Деньги за курс приходят в день покупки — это выручка того дня наравне со
 * стоимостью приёмов. Экран «Сегодня» без них показывал день беднее, чем он
 * был: продажа курса за 28 000 ₽ не появлялась нигде.
 */
export interface CourseSaleRow {
  id: string;
  amount: number;
  serviceTitle: string;
  sessionsTotal: number;
  patientName: string | null;
  /** Кто ведёт сеансы курса: по нему врач видит свою выручку. */
  staffId: string | null;
  staffName: string | null;
  /** Время покупки в поясе клиники, минуты от полуночи. */
  startMinute: number;
}

export async function getCourseSalesForDay(dateIso: string): Promise<CourseSaleRow[]> {
  const session = await getSession();
  const start = new Date(`${dateIso}T00:00:00+03:00`);
  if (Number.isNaN(start.getTime())) return [];
  const end = new Date(start.getTime() + 24 * 3600 * 1000);

  const rows = await coursePurchasesBetween(session.companyId, start, end);
  const minute = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Europe/Moscow",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });
  return rows.map((r) => {
    const [h, m] = minute.format(r.at).split(":");
    return {
      id: r.id,
      amount: r.amount,
      serviceTitle: r.serviceTitle,
      sessionsTotal: r.sessionsTotal,
      patientName: r.patientName,
      staffId: r.staffId,
      staffName: r.staffName,
      startMinute: Number(h) * 60 + Number(m),
    };
  });
}

export interface CourseRecord {
  patientId: string;
  id: string;
  title: string;
  /** Сеансы, которые СОСТОЯЛИСЬ. */
  used: number;
  total: number;
  /**
   * Записан, но ещё не пришёл: место в курсе занято, сеанс не пройден.
   *
   * Без этого числа «4 из 10» читается как брошенный курс, хотя человек уже
   * записан на оставшиеся шесть.
   */
  booked: number;
  status: "active" | "stalled" | "done";
  /** Подпись последнего сеанса: «сегодня», «3 дн.». */
  lastVisit: string;
  /** Он же числом — чтобы экраны не разбирали подпись обратно. */
  daysAgo: number | null;
  hasFuture: boolean;
  /** Цена сеанса из курса: деньги уже получены, это доля отработки. */
  pricePerSession: number;
}

/**
 * Сколько дней без сеанса считается «выпал».
 *
 * Здесь стояла константа 14. Ритм у услуг разный — БОС ходят раз в неделю,
 * остеопатию раз в месяц, — и одно число на всех означало, что половину зовут
 * рано, а половину поздно. Теперь порог берётся из услуги, а запасной задаёт
 * клиника в «Настройки → Клиника»; пусто — по таким услугам не звать вовсе.
 *
 * Экран курсов и очередь «Кому позвонить» обязаны считать это одинаково:
 * иначе на одном написано «выпал», на другом человека нет, и обе строки
 * одинаково не заслуживают доверия.
 */

export async function getCoursesForStore(): Promise<CourseRecord[]> {
  const session = await getSession();
  const now = new Date();
  const today = startOfClinicDay(now);

  const courses = await prisma.course.findMany({
    where: { companyId: session.companyId, status: { in: ["ACTIVE", "COMPLETED"] } },
    select: {
      id: true,
      patientId: true,
      sessionsTotal: true,
      sessionsUsed: true,
      sessionsBooked: true,
      pricePerSession: true,
      status: true,
      service: { select: { title: true, stalledAfterDays: true } },
      appointments: {
        where: { deletedAt: null, status: { not: "CANCELLED" } },
        select: { startAt: true },
        orderBy: { startAt: "desc" },
      },
    },
  });
  if (courses.length === 0) return [];

  /**
   * Будущая запись ищется по пациенту и услуге, а не по курсу.
   *
   * Следующий сеанс к курсу привяжется только после выгрузки, когда он уже
   * состоится. Пока он впереди, связи нет — и курс без неё выглядел бы
   * выпавшим при том, что человек записан на завтра.
   */
  const ahead = await prisma.appointment.findMany({
    where: {
      companyId: session.companyId,
      deletedAt: null,
      status: { not: "CANCELLED" },
      startAt: { gte: today },
      patientId: { in: [...new Set(courses.map((c) => c.patientId))] },
    },
    select: { patientId: true, primaryServiceId: true, services: { select: { serviceId: true } } },
  });
  const futureKeys = new Set<string>();
  for (const a of ahead) {
    const ids = new Set(a.services.map((s) => s.serviceId));
    if (a.primaryServiceId) ids.add(a.primaryServiceId);
    for (const id of ids) futureKeys.add(`${a.patientId}|${id}`);
  }

  const serviceIdOf = await prisma.course.findMany({
    where: { id: { in: courses.map((c) => c.id) } },
    select: { id: true, serviceId: true },
  });
  const svcByCourse = new Map(serviceIdOf.map((r) => [r.id, r.serviceId]));

  /** Запасной порог клиники — тот же, что у очереди «Кому позвонить». */
  const stalledFallback = await stalledFallbackDays(session.companyId);

  const todayKey = clinicDateKey(now);
  return courses.map((c) => {
    const last = c.appointments[0]?.startAt ?? null;
    const daysAgo =
      last === null
        ? null
        : Math.max(0, Math.round((today.getTime() - startOfClinicDay(last).getTime()) / 86_400_000));
    const hasFuture = futureKeys.has(`${c.patientId}|${svcByCourse.get(c.id) ?? ""}`);
    const limit = c.service.stalledAfterDays ?? stalledFallback;
    const done = c.status === "COMPLETED" || c.sessionsUsed >= c.sessionsTotal;
    return {
      patientId: c.patientId,
      id: c.id,
      title: c.service.title,
      used: c.sessionsUsed,
      total: c.sessionsTotal,
      /**
       * Записан, но ещё не пришёл. Показываем отдельно: место в курсе занято,
       * а сеанс не пройден. Без этого числа «4 из 10» выглядит как брошенный
       * курс, хотя человек уже записан на оставшиеся шесть.
       */
      booked: c.sessionsBooked,
      status:
        done
          ? "done"
          : // Порога нет ни у услуги, ни у клиники — «выпал» сказать не на чем.
            !hasFuture && daysAgo !== null && limit !== null && daysAgo > limit
            ? "stalled"
            : "active",
      lastVisit:
        last === null
          ? "нет сеансов"
          : clinicDateKey(last) === todayKey
            ? "сегодня"
            : `${daysAgo} дн.`,
      daysAgo,
      hasFuture,
      pricePerSession: Number(c.pricePerSession),
    } satisfies CourseRecord;
  });
}
